 13	public class Main {
 14	    private static final Logger logger = LoggerFactory.getLogger(Main.class);
 15	
 16	    public static void main(String[] args) {
 17	        try {
 18	            // Setup database
 19	            DataSource dataSource = DatabaseSetup.createDataSource();
 20	            DatabaseSetup.runMigrations(dataSource);
 21	
 22	            // Initialize repositories
 23	            var roomRepository = new PostgresRoomRepository(dataSource);
 24	            var reservationRepository = new PostgresReservationRepository(dataSource, roomRepository);
 25	            var notificationRepository = new PostgresNotificationRepository(dataSource);
 26	
 27	            // Create and start API
 28	            GuesthouseApi api = new GuesthouseApi(roomRepository, reservationRepository, notificationRepository);
 29	
 30	            int port = getPort();
 31	            api.start(port);
 32	
 33	            logger.info("Guesthouse API started successfully on port {}", port);
 34	        } catch (Exception e) {
 35	            logger.error("Failed to start application", e);
 36	            System.exit(1);
 37	        }
 38	    }
 39	
 40	    private static int getPort() {
 41	        String portEnv = System.getenv("PORT");
 42	        if (portEnv != null && !portEnv.isBlank()) {
 43	            try {
 44	                return Integer.parseInt(portEnv);
 45	            } catch (NumberFormatException e) {
 46	                logger.warn("Invalid PORT environment variable: {}, using default 7070", portEnv);
 47	            }
 48	        }
 49	        return 7070;
 50	    }
 51	}
