122	        app.get("/reservations/{id}", reservationsHandler::getReservation);
123	        app.post("/reservations/{id}/confirmation", reservationsHandler::confirmReservation);
124	        app.post("/reservations/{id}/cancellation", reservationsHandler::cancelReservation);
125	        app.post("/reservations/{id}/check-in", reservationsHandler::checkIn);
126	        app.post("/reservations/{id}/check-out", reservationsHandler::checkOut);
127	        app.get("/reservations/{id}/document", reservationsHandler::getDocument);
128	
129	        // Messages endpoint
130	        MessagesHandler messagesHandler = new MessagesHandler(notificationRepository);
131	        app.get("/messages", messagesHandler::listMessages);
132	
133	        // Reports endpoints
134	        ReportsHandler reportsHandler = new ReportsHandler(reservationRepository, roomRepository);
135	        app.get("/reports/occupancy", reportsHandler::occupancyReport);
136	        app.get("/reports/revenue", reportsHandler::revenueReport);
137	
138	        return app;
