192	    public OccupancyCalculator(ReservationRepository reservationRepository) {
193	        this.reservationRepository = reservationRepository;
194	    }
195	
196	    public void validateOccupancy(Room room, DateRange dates, int guestCount) {
197	        if (guestCount < 1) {
198	            throw new IllegalArgumentException("At least 1 guest required");
199	        }
200	
201	        if (guestCount > room.capacity()) {
202	            throw new IllegalArgumentException("Guest count exceeds room capacity");
203	        }
