213	import com.pousada.marealta.domain.notification.DomainEvent;
214	import com.pousada.marealta.domain.notification.NotificationSubscriber;
215	import com.pousada.marealta.domain.notification.PersistedNotification;
216	import com.pousada.marealta.domain.notification.ReservationCancelled;
217	import com.pousada.marealta.domain.notification.ReservationConfirmed;
218	import com.pousada.marealta.domain.pricing.RateCalculator;
219	import com.pousada.marealta.domain.pricing.RatePlan;
220	import com.pousada.marealta.domain.repository.NotificationRepository;
221	import com.pousada.marealta.domain.repository.ReservationRepository;
222	import com.pousada.marealta.domain.repository.RoomRepository;
223	import com.pousada.marealta.domain.reservation.Reservation;
224	import com.pousada.marealta.domain.reservation.ReservationStatus;
225	import com.pousada.marealta.domain.room.Room;
226	import com.pousada.marealta.domain.shared.DateRange;
227	import com.pousada.marealta.domain.shared.Guest;
228	import com.pousada.marealta.domain.shared.Money;
229	import org.slf4j.Logger;
230	import org.slf4j.LoggerFactory;
231	
232	import java.util.List;
233	import java.util.Optional;
234	
235	public class ReservationService {
236	    private static final Logger logger = LoggerFactory.getLogger(ReservationService.class);
237	
238	    private final ReservationRepository reservationRepository;
239	    private final RoomRepository roomRepository;
240	    private final NotificationRepository notificationRepository;
241	    private final OccupancyCalculator occupancyCalculator;
242	    private final List<NotificationSubscriber> notificationSubscribers;
243	
244	    public ReservationService(
245	            ReservationRepository reservationRepository,
246	            RoomRepository roomRepository,
247	            NotificationRepository notificationRepository,
248	            List<NotificationSubscriber> notificationSubscribers
249	    ) {
250	        this.reservationRepository = reservationRepository;
251	        this.roomRepository = roomRepository;
252	        this.notificationRepository = notificationRepository;
253	        this.occupancyCalculator = new OccupancyCalculator(reservationRepository);
254	        this.notificationSubscribers = notificationSubscribers;
255	    }
256	
257	    public ReservationRepository getReservationRepository() {
258	        return reservationRepository;
259	    }
260	
261	    public Reservation createReservation(CreateReservationRequest request) {
262	        // Validate input
263	        if (request.roomNumber <= 0) {
264	            throw new IllegalArgumentException("Invalid room number");
265	        }
266	        if (request.checkIn == null || request.checkOut == null) {
267	            throw new IllegalArgumentException("Check-in and check-out dates are required");
268	        }
269	
270	        // Get room
271	        Room room = roomRepository.findByNumber(request.roomNumber)
272	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
273	
274	        // Validate dates and occupancy
275	        DateRange dates = new DateRange(request.checkIn, request.checkOut);
276	        occupancyCalculator.validateOccupancy(room, dates, request.guests);
277	
278	        // Create guest
279	        Guest guest = new Guest(request.guestName, request.guestEmail, request.guestCpf);
280	
281	        // Calculate price
282	        RatePlan ratePlan = RatePlan.fromString(request.ratePlan);
283	        RateCalculator calculator = new RateCalculator(room.nightlyRate());
284	        var quote = calculator.quote(dates, ratePlan);
285	
286	        // Create reservation
287	        long reservationId = reservationRepository.nextId();
288	        Reservation reservation = new Reservation(
289	                reservationId,
290	                room,
291	                guest,
292	                dates,
293	                request.guests,
294	                ratePlan,
295	                quote.subtotal(),
296	                quote.discount(),
297	                quote.total()
298	        );
299	
300	        reservationRepository.save(reservation);
301	        logger.info("Created reservation {}", reservationId);
302	
303	        return reservation;
304	    }
305	
306	    public Reservation confirmReservation(long reservationId, Money amountPaid) {
307	        Reservation reservation = reservationRepository.findById(reservationId)
308	                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
309	
310	        if (reservation.status() != ReservationStatus.PENDING) {
311	            throw new IllegalStateException("Reservation is not pending");
312	        }
313	
314	        ReservationStatus previousStatus = reservation.status();
315	        reservation.confirm(amountPaid);
316	        reservationRepository.save(reservation);
317	
318	        // Emit event and dispatch to subscribers
319	        DomainEvent event = new ReservationConfirmed(reservation, previousStatus);
320	        dispatchEvent(event);
321	
322	        logger.info("Confirmed reservation {}", reservationId);
323	        return reservation;
324	    }
325	
326	    public Reservation checkIn(long reservationId) {
327	        Reservation reservation = reservationRepository.findById(reservationId)
328	                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
329	
330	        if (reservation.status() != ReservationStatus.CONFIRMED) {
331	            throw new IllegalStateException("Reservation is not confirmed");
332	        }
333	
334	        reservation.checkIn();
335	        reservationRepository.save(reservation);
336	
337	        logger.info("Checked in reservation {}", reservationId);
338	        return reservation;
339	    }
340	
341	    public Reservation checkOut(long reservationId) {
342	        Reservation reservation = reservationRepository.findById(reservationId)
343	                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
344	
345	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
346	            throw new IllegalStateException("Reservation is not checked in");
347	        }
348	
349	        reservation.checkOut();
350	        reservationRepository.save(reservation);
351	
352	        logger.info("Checked out reservation {}", reservationId);
353	        return reservation;
354	    }
355	
356	    public Reservation cancelReservation(long reservationId) {
357	        Reservation reservation = reservationRepository.findById(reservationId)
358	                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
359	
360	        if (reservation.status() == ReservationStatus.CHECKED_OUT ||
361	            reservation.status() == ReservationStatus.CANCELLED) {
362	            throw new IllegalStateException("Cannot cancel reservation with status " + reservation.status());
363	        }
364	
365	        ReservationStatus previousStatus = reservation.status();
366	        reservation.cancel();
367	        reservationRepository.save(reservation);
368	
369	        // Only dispatch event if reservation was confirmed
370	        if (previousStatus == ReservationStatus.CONFIRMED) {
371	            DomainEvent event = new ReservationCancelled(reservation, reservation.refund());
372	            dispatchEvent(event);
373	        }
374	
375	        logger.info("Cancelled reservation {}", reservationId);
376	        return reservation;
377	    }
378	
379	    private void dispatchEvent(DomainEvent event) {
380	        for (NotificationSubscriber subscriber : notificationSubscribers) {
381	            try {
382	                PersistedNotification notification = subscriber.handle(event);
383	                if (notification != null) {
384	                    notificationRepository.save(notification);
385	                }
386	            } catch (Exception e) {
387	                logger.error("Error dispatching event to subscriber {}", subscriber.name(), e);
388	            }
389	        }
390	    }
391	}

