334	public class GuestNotifier implements NotificationSubscriber {
335	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
336	
337	    @Override
338	    public String name() {
339	        return "GuestNotifier";
340	    }
341	
342	    @Override
343	    public PersistedNotification handle(DomainEvent event) {
344	        if (event instanceof ReservationConfirmed) {
345	            return handleConfirmed((ReservationConfirmed) event);
346	        } else if (event instanceof ReservationCancelled) {
347	            return handleCancelled((ReservationCancelled) event);
348	        }
349	        return null;
350	    }
351	
352	    private PersistedNotification handleConfirmed(ReservationConfirmed event) {
353	        Reservation reservation = event.reservation();
354	        String receipt = buildReceipt(reservation);
355	
356	        String subject = "Reserva confirmada - Pousada Maré Alta";
357	        String body = buildConfirmationEmail(reservation, receipt);
358	
359	        return PersistedNotification.success(
360	                reservation.id(),
361	                "EMAIL",
362	                reservation.guest().email(),
363	                subject,
364	                body
365	        );
366	    }
367	
368	    private PersistedNotification handleCancelled(ReservationCancelled event) {
369	        // Guest gets notified about cancellation
370	        Reservation reservation = event.reservation();
371	
372	        String subject = "Reserva cancelada - Pousada Maré Alta";
373	        String body = "Sua reserva #" + reservation.id() + " foi cancelada.";
374	
375	        return PersistedNotification.success(
376	                reservation.id(),
377	                "EMAIL",
378	                reservation.guest().email(),
379	                subject,
380	                body
381	        );
382	    }
383	
384	    private String buildConfirmationEmail(Reservation reservation, String receipt) {
385	        return String.format(
386	                "Olá, %s!\n\n" +
387	                "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
388	                "%s\n\n" +
389	                "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
390	                "Até breve!",
391	                reservation.guest().name(),
392	                receipt
393	        );
394	    }
395	
396	    private String buildReceipt(Reservation reservation) {
397	        StringBuilder sb = new StringBuilder();
398	        sb.append("Comprovante de reserva nº ").append(reservation.id()).append("\n");
399	        sb.append("Hóspede: ").append(reservation.guest().name()).append(" (CPF ").append(reservation.guest().cpf()).append(")\n");
400	        sb.append("Quarto: ").append(reservation.room().number()).append(" (").append(reservation.room().type().displayName()).append(")\n");
401	        sb.append("Entrada: ").append(formatDate(reservation.dates().checkIn())).append(" | ");
402	        sb.append("Saída: ").append(formatDate(reservation.dates().checkOut())).append(" | ");
403	        sb.append(formatNights(reservation.dates().nights())).append("\n");
404	        sb.append("Diárias: ").append(formatMoney(reservation.subtotal())).append("\n");
405	
406	        if (reservation.discount().doubleValue() > 0) {
407	            sb.append("Desconto: ").append(formatMoney(reservation.discount())).append("\n");
408	        }
409	
410	        sb.append("Total: ").append(formatMoney(reservation.total()));
411	
412	        return sb.toString();
413	    }
414	
415	    private String formatDate(java.time.LocalDate date) {
416	        return date.format(DATE_FORMAT);
417	    }
418	
419	    private String formatNights(int nights) {
420	        return nights == 1 ? "1 diária" : nights + " diárias";
421	    }
422	
423	    private String formatMoney(com.pousada.marealta.domain.shared.Money money) {
424	        return String.format("R$ %.2f", money.doubleValue());
425	    }
426	}

