 11	public class Reservation {
 12	    private final long id;
 13	    private final Room room;
 14	    private final Guest guest;
 15	    private final DateRange dates;
 16	    private final int guestCount;
 17	    private final RatePlan ratePlan;
 18	    private final Money subtotal;
 19	    private final Money discount;
 20	    private final Money total;
 21	    private ReservationStatus status;
 22	    private Money amountPaid;
 23	    private Money refund;
 24	    private final LocalDateTime createdAt;
 25	
 26	    public Reservation(
 27	            long id,
 28	            Room room,
 29	            Guest guest,
 30	            DateRange dates,
 31	            int guestCount,
 32	            RatePlan ratePlan,
 33	            Money subtotal,
 34	            Money discount,
 35	            Money total
 36	    ) {
 37	        Objects.requireNonNull(room, "Room cannot be null");
 38	        Objects.requireNonNull(guest, "Guest cannot be null");
 39	        Objects.requireNonNull(dates, "Date range cannot be null");
 40	        Objects.requireNonNull(ratePlan, "Rate plan cannot be null");
 41	        Objects.requireNonNull(subtotal, "Subtotal cannot be null");
 42	        Objects.requireNonNull(discount, "Discount cannot be null");
 43	        Objects.requireNonNull(total, "Total cannot be null");
 44	
 45	        if (guestCount < 1) {
 46	            throw new IllegalArgumentException("Guest count must be at least 1");
 47	        }
 48	        if (guestCount > room.capacity()) {
 49	            throw new IllegalArgumentException("Guest count exceeds room capacity");
 50	        }
 51	
 52	        this.id = id;
 53	        this.room = room;
 54	        this.guest = guest;
 55	        this.dates = dates;
 56	        this.guestCount = guestCount;
 57	        this.ratePlan = ratePlan;
 58	        this.subtotal = subtotal;
 59	        this.discount = discount;
 60	        this.total = total;
 61	        this.status = ReservationStatus.PENDING;
 62	        this.amountPaid = Money.ofCents(0);
 63	        this.refund = null;
 64	        this.createdAt = LocalDateTime.now();
 65	    }
 66	
 67	    public long id() {
 68	        return id;
 69	    }
 70	
 71	    public Room room() {
 72	        return room;
 73	    }
 74	
 75	    public Guest guest() {
 76	        return guest;
 77	    }
 78	
 79	    public DateRange dates() {
 80	        return dates;
 81	    }
 82	
 83	    public int guestCount() {
 84	        return guestCount;
 85	    }
 86	
 87	    public RatePlan ratePlan() {
 88	        return ratePlan;
 89	    }
 90	
 91	    public Money subtotal() {
 92	        return subtotal;
 93	    }
 94	
 95	    public Money discount() {
 96	        return discount;
 97	    }
 98	
 99	    public Money total() {
100	        return total;
101	    }
102	
103	    public ReservationStatus status() {
104	        return status;
105	    }
106	
107	    public Money amountPaid() {
108	        return amountPaid;
109	    }
110	
111	    public Money refund() {
112	        return refund;
113	    }
114	
115	    public LocalDateTime createdAt() {
116	        return createdAt;
117	    }
118	
119	    public void confirm(Money amountPaid) {
120	        if (status != ReservationStatus.PENDING) {
121	            throw new IllegalStateException("Cannot confirm reservation with status " + status);
122	        }
123	        Objects.requireNonNull(amountPaid, "Amount paid cannot be null");
124	        if (amountPaid.doubleValue() <= 0) {
125	            throw new IllegalArgumentException("Amount paid must be positive");
126	        }
127	
128	        this.status = ReservationStatus.CONFIRMED;
129	        this.amountPaid = amountPaid;
130	    }
131	
132	    public void checkIn() {
133	        if (status != ReservationStatus.CONFIRMED) {
134	            throw new IllegalStateException("Cannot check in reservation with status " + status);
135	        }
136	        this.status = ReservationStatus.CHECKED_IN;
137	    }
138	
139	    public void checkOut() {
140	        if (status != ReservationStatus.CHECKED_IN) {
141	            throw new IllegalStateException("Cannot check out reservation with status " + status);
142	        }
143	        this.status = ReservationStatus.CHECKED_OUT;
144	    }
145	
146	    public void cancel() {
147	        if (status == ReservationStatus.CHECKED_OUT || status == ReservationStatus.CANCELLED) {
148	            throw new IllegalStateException("Cannot cancel reservation with status " + status);
149	        }
150	
151	        if (status == ReservationStatus.CONFIRMED) {
152	            // Calculate refund based on rate plan
153	            if (ratePlan == RatePlan.STANDARD) {
154	                this.refund = amountPaid;
155	            } else if (ratePlan == RatePlan.NON_REFUNDABLE) {
156	                this.refund = Money.ofCents(0);
157	            }
158	        } else if (status == ReservationStatus.PENDING) {
159	            // No payment was made
160	            this.refund = Money.ofCents(0);
161	        } else if (status == ReservationStatus.CHECKED_IN) {
162	            // Cannot cancel during or after check-in
163	            throw new IllegalStateException("Cannot cancel a checked-in reservation");
164	        }
165	
166	        this.status = ReservationStatus.CANCELLED;
167	    }
168	
169	    @Override
170	    public boolean equals(Object o) {
171	        if (this == o) return true;
172	        if (!(o instanceof Reservation)) return false;
173	        Reservation that = (Reservation) o;
174	        return id == that.id;
175	    }
176	
177	    @Override
178	    public int hashCode() {
179	        return Objects.hash(id);
180	    }
181	}
