215	public class DateRange {
216	    private final LocalDate checkIn;
217	    private final LocalDate checkOut;
218	
219	    public DateRange(LocalDate checkIn, LocalDate checkOut) {
220	        Objects.requireNonNull(checkIn, "Check-in date cannot be null");
221	        Objects.requireNonNull(checkOut, "Check-out date cannot be null");
222	        if (!checkIn.isBefore(checkOut)) {
223	            throw new IllegalArgumentException("Check-in must be before check-out");
224	        }
225	        this.checkIn = checkIn;
226	        this.checkOut = checkOut;
227	    }
