229	    public LocalDate checkIn() {
230	        return checkIn;
231	    }
232	
233	    public LocalDate checkOut() {
234	        return checkOut;
235	    }
236	
237	    public int nights() {
238	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
239	    }
240	
241	    public boolean overlaps(DateRange other) {
242	        return !this.checkOut.isAfter(other.checkIn) == false &&
243	               !this.checkIn.isBefore(other.checkOut) == false;
244	    }
245	
246	    public boolean contains(LocalDate date) {
247	        return !date.isBefore(checkIn) && date.isBefore(checkOut);
248	    }
249	
250	    @Override
251	    public boolean equals(Object o) {
252	        if (this == o) return true;
253	        if (!(o instanceof DateRange)) return false;
254	        DateRange dateRange = (DateRange) o;
255	        return checkIn.equals(dateRange.checkIn) && checkOut.equals(dateRange.checkOut);
256	    }
257	
258	    @Override
259	    public int hashCode() {
260	        return Objects.hash(checkIn, checkOut);
261	    }
262	
263	    @Override
264	    public String toString() {
265	        return checkIn + " to " + checkOut + " (" + nights() + " nights)";
266	    }
267	}
