343	public class Money {
344	    private final BigDecimal amount;
345	
346	    private Money(BigDecimal amount) {
347	        this.amount = amount.setScale(2, RoundingMode.HALF_EVEN);
348	    }
349	
350	    public static Money ofCents(long cents) {
351	        return new Money(BigDecimal.valueOf(cents, 2));
352	    }
353	
354	    public static Money of(double value) {
355	        return new Money(BigDecimal.valueOf(value));
356	    }
357	
358	    public static Money of(BigDecimal value) {
359	        return new Money(value);
360	    }
361	
362	    public Money add(Money other) {
363	        return new Money(this.amount.add(other.amount));
364	    }
365	
366	    public Money subtract(Money other) {
367	        return new Money(this.amount.subtract(other.amount));
368	    }
369	
370	    public Money multiply(BigDecimal factor) {
371	        return new Money(this.amount.multiply(factor));
372	    }
373	
374	    public Money multiply(double factor) {
375	        return multiply(BigDecimal.valueOf(factor));
376	    }
377	
378	    public Money applyPercent(int percent) {
379	        BigDecimal factor = BigDecimal.valueOf(1).add(BigDecimal.valueOf(percent).divide(BigDecimal.valueOf(100)));
380	        return multiply(factor);
381	    }
382	
383	    public Money discount(int percent) {
384	        BigDecimal factor = BigDecimal.ONE.subtract(BigDecimal.valueOf(percent).divide(BigDecimal.valueOf(100)));
385	        return multiply(factor);
386	    }
387	
388	    public long cents() {
389	        return amount.unscaledValue().longValue();
390	    }
391	
392	    public BigDecimal value() {
393	        return amount;
394	    }
395	
396	    public double doubleValue() {
397	        return amount.doubleValue();
398	    }
399	
400	    @Override
401	    public String toString() {
402	        return String.format("R$ %.2f", amount);
403	    }
404	
405	    @Override
406	    public boolean equals(Object o) {
407	        if (this == o) return true;
408	        if (!(o instanceof Money)) return false;
409	        Money money = (Money) o;
410	        return amount.compareTo(money.amount) == 0;
411	    }
412	
413	    @Override
414	    public int hashCode() {
415	        return amount.hashCode();
416	    }
417	}
