423	public enum Season {
424	    HIGH_SEASON(1.20),
425	    REGULAR(1.0);
426	
427	    private final double multiplier;
428	
429	    Season(double multiplier) {
430	        this.multiplier = multiplier;
431	    }
432	
433	    public double multiplier() {
434	        return multiplier;
435	    }
436	
437	    public static Season forDate(LocalDate date) {
438	        Month month = date.getMonth();
439	        int dayOfMonth = date.getDayOfMonth();
440	
441	        if (month == Month.JULY) {
442	            return HIGH_SEASON;
443	        }
444	
445	        if (month == Month.DECEMBER && dayOfMonth >= 15) {
446	            return HIGH_SEASON;
447	        }
448	
449	        if ((month == Month.JANUARY || month == Month.FEBRUARY) && dayOfMonth <= 28) {
450	            return HIGH_SEASON;
451	        }
452	
453	        return REGULAR;
454	    }
455	}
