 30	import com.pousada.marealta.domain.room.Room;
 31	import io.javalin.http.Context;
 32	import io.javalin.http.HttpStatus;
 33	import org.slf4j.Logger;
 34	import org.slf4j.LoggerFactory;
 35	
 36	import java.time.LocalDate;
 37	import java.time.YearMonth;
 38	import java.time.format.DateTimeFormatter;
 39	import java.util.List;
 40	import java.util.stream.Collectors;
 41	
 42	public class ReportsHandler {
 43	    private static final Logger logger = LoggerFactory.getLogger(ReportsHandler.class);
 44	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 45	    private static final DateTimeFormatter MONTH_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM");
 46	
 47	    private final ReservationRepository reservationRepository;
 48	    private final RoomRepository roomRepository;
 49	
 50	    public ReportsHandler(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 51	        this.reservationRepository = reservationRepository;
 52	        this.roomRepository = roomRepository;
 53	    }
 54	
 55	    public void occupancyReport(Context ctx) {
 56	        try {
 57	            String dateStr = ctx.queryParam("date");
 58	            if (dateStr == null || dateStr.isBlank()) {
 59	                ctx.status(HttpStatus.BAD_REQUEST);
 60	                ctx.result("Missing required query parameter: date");
 61	                return;
 62	            }
 63	
 64	            LocalDate date = LocalDate.parse(dateStr, DATE_FORMAT);
 65	            List<Reservation> confirmedReservations = reservationRepository.findConfirmedByDate(date);
 66	            List<Room> allRooms = roomRepository.findAll();
 67	
 68	            StringBuilder csv = new StringBuilder();
 69	            csv.append("room,type,reservation,check_in,check_out\n");
 70	
 71	            for (Room room : allRooms) {
 72	                var reservation = confirmedReservations.stream()
 73	                        .filter(r -> r.room().number() == room.number())
 74	                        .findFirst();
 75	
 76	                if (reservation.isPresent()) {
 77	                    Reservation res = reservation.get();
 78	                    csv.append(room.number()).append(",")
 79	                            .append(room.type().displayName()).append(",")
 80	                            .append(res.id()).append(",")
 81	                            .append(res.dates().checkIn().format(DATE_FORMAT)).append(",")
 82	                            .append(res.dates().checkOut().format(DATE_FORMAT)).append("\n");
 83	                }
 84	            }
 85	
 86	            int occupied = (int) confirmedReservations.stream()
 87	                    .map(r -> r.room().number())
 88	                    .distinct()
 89	                    .count();
 90	            csv.append("total,").append(occupied).append("/").append(allRooms.size());
 91	
 92	            ctx.contentType("text/csv; charset=utf-8");
 93	            ctx.result(csv.toString());
 94	        } catch (Exception e) {
 95	            logger.error("Error generating occupancy report", e);
 96	            ctx.status(HttpStatus.BAD_REQUEST);
 97	            ctx.result("Invalid date format. Use yyyy-MM-dd");
 98	        }
 99	    }
100	
101	    public void revenueReport(Context ctx) {
102	        try {
103	            String monthStr = ctx.queryParam("month");
104	            if (monthStr == null || monthStr.isBlank()) {
105	                ctx.status(HttpStatus.BAD_REQUEST);
106	                ctx.result("Missing required query parameter: month");
107	                return;
108	            }
109	
110	            YearMonth month = YearMonth.parse(monthStr, MONTH_FORMAT);
111	            List<Reservation> reservations = reservationRepository.findByMonth(month);
112	
113	            StringBuilder csv = new StringBuilder();
114	            csv.append("reservation,room,check_in,check_out,status,amount\n");
115	
116	            for (Reservation res : reservations) {
117	                csv.append(res.id()).append(",")
118	                        .append(res.room().number()).append(",")
119	                        .append(res.dates().checkIn().format(DATE_FORMAT)).append(",")
120	                        .append(res.dates().checkOut().format(DATE_FORMAT)).append(",")
121	                        .append(res.status().displayName()).append(",")
