222	    public void confirmReservation(Context ctx) {
223	        try {
224	            long id = Long.parseLong(ctx.pathParam("id"));
225	            String body = ctx.body();
226	
227	            // Parse amount from body { "amount": 123.45 }
228	            var json = gson.fromJson(body, java.util.Map.class);
229	            double amount = (double) json.getOrDefault("amount", 0.0);
230	
231	            if (amount <= 0) {
232	                ctx.status(HttpStatus.BAD_REQUEST);
233	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Amount must be positive"));
234	                return;
235	            }
236	
237	            Money amountPaid = Money.of(amount);
238	            Reservation reservation = reservationService.confirmReservation(id, amountPaid);
239	
240	            ctx.json(ReservationDTO.fromDomain(reservation));
241	        } catch (IllegalArgumentException e) {
242	            handleError(ctx, e.getMessage());
243	        } catch (IllegalStateException e) {
244	            ctx.status(HttpStatus.CONFLICT);
245	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
246	        } catch (Exception e) {
