326	    private void handleError(Context ctx, String message) {
327	        if (message.contains("Room not found")) {
328	            ctx.status(HttpStatus.NOT_FOUND);
329	            ctx.json(new ErrorResponse("ROOM_NOT_FOUND", message));
330	        } else if (message.contains("Reservation not found")) {
331	            ctx.status(HttpStatus.NOT_FOUND);
332	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", message));
333	        } else if (message.contains("already booked")) {
334	            ctx.status(HttpStatus.CONFLICT);
335	            ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", message));
336	        } else if (message.contains("exceeds room capacity")) {
337	            ctx.status(422);
338	            ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", message));
339	        } else {
340	            ctx.status(HttpStatus.BAD_REQUEST);
341	            ctx.json(new ErrorResponse("INVALID_REQUEST", message));
