238	    private Reservation mapRowToReservation(ResultSet rs) throws SQLException {
239	        long id = rs.getLong("id");
240	        int roomNumber = rs.getInt("room_number");
241	        String guestName = rs.getString("guest_name");
242	        String guestEmail = rs.getString("guest_email");
243	        String guestCpf = rs.getString("guest_cpf");
244	        LocalDate checkIn = rs.getDate("check_in").toLocalDate();
245	        LocalDate checkOut = rs.getDate("check_out").toLocalDate();
246	        int guestCount = rs.getInt("guest_count");
247	        RatePlan ratePlan = RatePlan.fromString(rs.getString("rate_plan"));
248	        Money subtotal = Money.ofCents(rs.getLong("subtotal_cents"));
249	        Money discount = Money.ofCents(rs.getLong("discount_cents"));
250	        Money total = Money.ofCents(rs.getLong("total_cents"));
251	        ReservationStatus status = ReservationStatus.fromString(rs.getString("status"));
252	        Money amountPaid = Money.ofCents(rs.getLong("amount_paid_cents"));
253	        Long refundCents = (Long) rs.getObject("refund_cents");
254	        Money refund = refundCents != null ? Money.ofCents(refundCents) : null;
255	
256	        Room room = roomRepository.findByNumber(roomNumber)
257	                .orElseThrow(() -> new RuntimeException("Room not found: " + roomNumber));
258	
259	        Guest guest = new Guest(guestName, guestEmail, guestCpf);
260	        DateRange dates = new DateRange(checkIn, checkOut);
261	
262	        Reservation reservation = new Reservation(
263	                id, room, guest, dates, guestCount, ratePlan, subtotal, discount, total
264	        );
265	
266	        // Restore state from database
267	        if (status == ReservationStatus.CONFIRMED || status == ReservationStatus.CHECKED_IN ||
268	            status == ReservationStatus.CHECKED_OUT) {
269	            reservation.confirm(amountPaid);
270	        }
271	
272	        if (status == ReservationStatus.CHECKED_IN || status == ReservationStatus.CHECKED_OUT) {
273	            reservation.checkIn();
274	        }
275	
276	        if (status == ReservationStatus.CHECKED_OUT) {
277	            reservation.checkOut();
278	        }
279	
280	        if (status == ReservationStatus.CANCELLED) {
281	            reservation.cancel();
282	            // Set refund if it was stored
283	            if (refund != null) {
284	                // We need to reflect the refund in the object
